python3 - <<'PY'
import csv

def totals(path):
    with open(path,newline='') as f:
        r=csv.DictReader(f)
        beg=0.0
        adds={m:0.0 for m in ['jan','feb','mar','apr']}
        amort={m:0.0 for m in ['jan','feb','mar','apr']}
        end={m:0.0 for m in ['jan','feb','mar','apr']}
        for row in r:
            if not row.get('vendor'): continue
            beg += float(row['beginning_balance'])
            for m in adds:
                adds[m]+= float(row[f'{m}_adds'])
                amort[m]+= float(row[f'{m}_amortization'])
                end[m]+= float(row[f'{m}_ending_balance'])
    net={m:round(adds[m]-amort[m],2) for m in adds}
    return round(beg,2), {m:round(adds[m],2) for m in adds}, {m:round(amort[m],2) for m in amort}, net, {m:round(end[m],2) for m in end}

for path in ['/root/compute_capacity_schedule_input.csv','/root/storage_capacity_schedule_input.csv']:
    beg, adds, amort, net, end = totals(path)
    print('==',path)
    print('beg',beg)
    print('adds',adds)
    print('amort',amort)
    print('net',net)
    # rollforward check
    running=beg
    for m in ['jan','feb','mar','apr']:
        running = round(running+net[m],2)
        print(m,'calc_end',running,'csv_end',end[m], 'diff', round(running-end[m],2))
    print()
PY

